import{_ as n,C as a,o as p,c as l,j as d,a as e,E as o,ah as c}from"./chunks/framework.BpF7DVZ1.js";const q=JSON.parse('{"title":"提示输入框","description":"","frontmatter":{},"headers":[],"relativePath":"components/prompt-input.md","filePath":"components/prompt-input.md","lastUpdated":1788635489000}'),s={name:"components/prompt-input.md"},h={id:"提示输入框",tabindex:"-1"};function u(b,t,m,x,g,f){const i=a("Badge"),r=a("XhDemo");return p(),l("div",null,[d("h1",h,[t[0]||(t[0]=e("提示输入框 ",-1)),o(i,{type:"info",text:"prompt-input"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#提示输入框","aria-label":'Permalink to "提示输入框 <Badge type="info" text="prompt-input" />"'},"​",-1))]),t[3]||(t[3]=c('<p>会话界面的输入框：值、输入法、能不能提交，以及发送与停止共用的那一颗按钮。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>AI 对话、聊天或任何「输入一段话然后提交」的界面。</li><li>生成期间要能一键停止。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是表单里的一个多行文本域：用<a href="./text-field">文本框</a>配<a href="./field">字段</a>。</li><li>要 @提及或斜杠命令：整个用<a href="./mention">提及</a>当输入器，见下方的组合。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>发送与停止<strong>原位共用一个节点</strong>：正在按它的用户不会按空。生成期间按钮恒可用， 此刻它的语义是停止。</li><li><code>submitKey</code> 一个 prop 表达三档：<code>enter</code> 档 Enter 提交、Shift+Enter 换行、Mod+Enter 也提交； <code>mod-enter</code> 档 Enter 换行，只有 Mod+Enter 提交；<code>none</code> 档两种按法都换行， 键盘一个提交出口都不留，只剩发送按钮与程序化的 <code>submit()</code>。</li><li>输入法组合期间的 Enter 一律放行，那一下是在确认候选词。</li><li>同一个输入框上叠了别的处理器且它已经处理过这一下时，组件让位。</li><li>自动长高是两行 CSS，不进状态机；引擎不支持时退化成 <code>rows</code> 定的固定行数。</li><li>两种排布同一份皮肤：直接把输入框与按钮放进 root 就是单行；套一层输入行，root 翻成竖排， 输入行上下两侧就能再放附件条与动作行。</li><li>发送按钮留空时皮肤画兜底字形：发送身份一枚上箭头，停止身份一枚圆角方块； 塞进自己的图标或文案即盖掉它。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>Enter 提交、Shift+Enter 换行；输入法组合中的 Enter 一律放行，那一下是在确认候选词</p>',10)),o(r,{src:"prompt-input/01-basic"}),t[4]||(t[4]=d("h3",{id:"与消息流合成一个对话",tabindex:"-1"},[e("与消息流合成一个对话 "),d("a",{class:"header-anchor",href:"#与消息流合成一个对话","aria-label":'Permalink to "与消息流合成一个对话"'},"​")],-1)),t[5]||(t[5]=d("p",null,"发送键原位变停止；提交后粘底跟到最新一条，生成期间还能接着改下一句",-1)),o(r,{src:"prompt-input/02-chat"}),t[6]||(t[6]=d("h3",{id:"竖排布局与兜底字形",tabindex:"-1"},[e("竖排布局与兜底字形 "),d("a",{class:"header-anchor",href:"#竖排布局与兜底字形","aria-label":'Permalink to "竖排布局与兜底字形"'},"​")],-1)),t[7]||(t[7]=d("p",null,"写一层输入行，root 就翻成竖排：输入行在上、动作行在下；按钮留空时皮肤按身份画上箭头或停止方块",-1)),o(r,{src:"prompt-input/03-layout"}),t[8]||(t[8]=d("h3",{id:"三档提交按键",tabindex:"-1"},[e("三档提交按键 "),d("a",{class:"header-anchor",href:"#三档提交按键","aria-label":'Permalink to "三档提交按键"'},"​")],-1)),t[9]||(t[9]=d("p",null,"enter 档回车就发、mod-enter 档只有 Ctrl/Cmd+Enter 发、none 档两种按法都换行，提交只剩发送按钮",-1)),o(r,{src:"prompt-input/04-submit-key"}),t[10]||(t[10]=d("h3",{id:"禁用与空值",tabindex:"-1"},[e("禁用与空值 "),d("a",{class:"header-anchor",href:"#禁用与空值","aria-label":'Permalink to "禁用与空值"'},"​")],-1)),t[11]||(t[11]=d("p",null,"disabled 罩住整框并走原生 disabled；输入为空或只有空白时发送按钮转灰，但位置留着不收起",-1)),o(r,{src:"prompt-input/05-disabled"}),t[12]||(t[12]=d("h3",{id:"框里的附加节点",tabindex:"-1"},[e("框里的附加节点 "),d("a",{class:"header-anchor",href:"#框里的附加节点","aria-label":'Permalink to "框里的附加节点"'},"​")],-1)),t[13]||(t[13]=d("p",null,"root 里除三件外还能放自己的按钮与计数；值的读写归宿主，原生属性照旧直接落到输入框上",-1)),o(r,{src:"prompt-input/06-extras"}),t[14]||(t[14]=d("h3",{id:"随内容长高",tabindex:"-1"},[e("随内容长高 "),d("a",{class:"header-anchor",href:"#随内容长高","aria-label":'Permalink to "随内容长高"'},"​")],-1)),t[15]||(t[15]=d("p",null,"输入框的高度跟着内容走，rows 定的是起始行数；不手动拖拽，也不写死高度",-1)),o(r,{src:"prompt-input/07-autosize"}),t[16]||(t[16]=d("h3",{id:"聚焦与选中",tabindex:"-1"},[e("聚焦与选中 "),d("a",{class:"header-anchor",href:"#聚焦与选中","aria-label":'Permalink to "聚焦与选中"'},"​")],-1)),t[17]||(t[17]=d("p",null,"输入部件就是一个原生 textarea，拿到它的节点就能聚焦、全选、失焦；发完一条把焦点送回去，接着敲下一条",-1)),o(r,{src:"prompt-input/08-focus"}),t[18]||(t[18]=d("h3",{id:"发送失败的错误态",tabindex:"-1"},[e("发送失败的错误态 "),d("a",{class:"header-anchor",href:"#发送失败的错误态","aria-label":'Permalink to "发送失败的错误态"'},"​")],-1)),t[19]||(t[19]=d("p",null,"判定谁算出错是宿主的事：属性直接落到真元素上，整框换色靠覆盖公开变量，原因由活区播报",-1)),o(r,{src:"prompt-input/09-invalid"}),t[20]||(t[20]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[21]||(t[21]=d("p",null,"tone 换聚焦描边与发送钮用哪族颜色，输入与提交那条链不受影响",-1)),o(r,{src:"prompt-input/10-tone"}),t[22]||(t[22]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-prompt-input&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPromptInputControl</code> <code>XhPromptInputInput</code> <code>XhPromptInputRoot</code> <code>XhPromptInputSubmitTrigger</code></td></tr><tr><td>组合式函数</td><td><code>usePromptInput</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/prompt-input.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;prompt-input&quot;</code>：<strong><code>root</code></strong> · <code>control</code> · <strong><code>input</code></strong> · <strong><code>submit-trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>正在生成：按钮换成停止身份，所有提交路径被挡下。 用一个布尔而不是四档运行态字符串——组件只需要二值判断， 「这一轮走到哪一步」是宿主的事，透传成 data 属性属于作者的容器。</td></tr><tr><td><code>submitKey</code></td><td><code>PromptInputSubmitKey</code></td><td></td><td>按哪一档提交，默认 enter。</td></tr><tr><td><code>allowEmptySubmit</code></td><td><code>boolean</code></td><td></td><td>允许空值提交，默认 false；有附件时由作者置真。这是唯一为附件留的钩子。</td></tr><tr><td><code>clearOnSubmit</code></td><td><code>boolean</code></td><td></td><td>提交后清空，默认 true。</td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;PromptInputTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: PromptInputValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onSubmit</code></td><td><code>(details: PromptInputSubmitDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onStop</code></td><td><code>() =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>PromptInputValueChangeDetails</code></td><td>值变化；detail 为 <code>{ value: string }</code></td></tr><tr><td><code>submit</code></td><td><code>PromptInputSubmitDetails</code></td><td>提交；detail 为 <code>{ value: string }</code>，清空发生在派发之后。 与原生表单提交同名，故不冒泡，请直接在 <code>&amp;lt;xh-prompt-input&amp;gt;</code> 元素上监听</td></tr><tr><td><code>stop</code></td><td>``</td><td>生成期间按下停止；无 detail</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPromptInputRoot</code></td><td><code>default</code></td><td><code>PromptInputRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>input</code></td><td>state.get()</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>COMPOSITION.START</code> · <code>COMPOSITION.END</code> · <code>KEY.SUBMIT</code> · <code>SUBMIT</code> · <code>STOP</code> · <code>CONTROLLED.DISABLE</code> · <code>CONTROLLED.ENABLE</code> · <code>CONTROLLED.VALUE.EMPTY</code> · <code>CONTROLLED.VALUE.FILLED</code></p><p><strong>判据</strong>：<code>canSubmit</code> · <code>isLoading</code> · <code>isValueEmpty</code> · <code>isNextValueEmpty</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>usePromptInput</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td></tr><tr><td><code>isComposing</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>canSubmit</code></td><td><code>boolean</code></td><td>能不能提交。比机器守卫多一条「非禁用」，供按钮置灰用。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td></td></tr><tr><td><code>submit</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>stop</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>可选的输入行容器：渲了它，输入框与按钮并排收在这一行里，root 翻成竖排。</td></tr><tr><td><code>getInputProps</code></td><td><code>() =&gt; T[&#39;textarea&#39;]</code></td><td></td></tr><tr><td><code>getSubmitTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Understanding/keyboard" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>焦点在输入框、submitKey 为 enter、非组合态、可提交，且这一下还没被别的处理器处理过</td><td>提交，并按 clearOnSubmit 决定清不清空</td></tr><tr><td><code>Shift+Enter</code></td><td>焦点在输入框</td><td>不归组件管：原样放行，浏览器插入换行</td></tr><tr><td><code>Control+Enter</code> / <code>Meta+Enter</code></td><td>焦点在输入框、submitKey 为 enter 或 mod-enter、非组合态、可提交</td><td>提交，并按 clearOnSubmit 决定清不清空</td></tr><tr><td><code>Enter</code> / <code>Control+Enter</code> / <code>Meta+Enter</code></td><td>焦点在输入框、submitKey 为 none</td><td>都不提交也不拦截：原样放行，浏览器插入换行；提交只剩按钮与程序化两条路</td></tr><tr><td><code>Enter</code></td><td>输入法组合中</td><td>不提交也不拦截：这一下是在确认候选词</td></tr><tr><td><code>Enter</code></td><td>同一个输入框上叠了别的处理器且它已经处理过这一下</td><td>让位，本组件什么都不做</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在发送按钮上</td><td>按当前身份触发提交或停止（原生按钮激活）</td></tr><tr><td><code>Escape</code></td><td>任何时候</td><td>不接管：留给叠在输入框上的浮层与页面</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>aria-label</code></td><td>translations?.input</td></tr><tr><td><code>submit-trigger</code></td><td><code>aria-label</code></td><td>translations?.stop | translations?.send</td></tr></tbody></table><ul><li>输入框的可访问名<strong>只在给了 <code>translations.input</code> 时才发</strong>：无条件发会盖掉作者自己的 <code>&lt;label for&gt;</code> 与 <code>aria-label</code>。</li><li>按钮的可访问名随身份翻面，读屏念到的与屏幕上看到的是同一件事。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/prompt-input.css</code> 按部件选择：<code>[data-scope=&quot;prompt-input&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>input</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>submit-trigger</code></td><td><code>data-mode</code></td><td>&#39;stop&#39; | &#39;send&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-prompt-input-bg</code> · <code>--xh-prompt-input-bg-disabled</code> · <code>--xh-prompt-input-bg-hover</code> · <code>--xh-prompt-input-border</code> · <code>--xh-prompt-input-border-focus</code> · <code>--xh-prompt-input-border-hover</code> · <code>--xh-prompt-input-gap</code> · <code>--xh-prompt-input-icon-size</code> · <code>--xh-prompt-input-input-autofill-bg</code> · <code>--xh-prompt-input-input-autofill-fg</code> · <code>--xh-prompt-input-input-fg</code> · <code>--xh-prompt-input-input-font-size</code> · <code>--xh-prompt-input-max-h</code> · <code>--xh-prompt-input-p</code> · <code>--xh-prompt-input-placeholder-fg</code> · <code>--xh-prompt-input-radius</code> · <code>--xh-prompt-input-row-gap</code> · <code>--xh-prompt-input-send-bg</code> · <code>--xh-prompt-input-send-bg-active</code> · <code>--xh-prompt-input-send-bg-hover</code> · <code>--xh-prompt-input-send-bg-off</code> · <code>--xh-prompt-input-send-fg</code> · <code>--xh-prompt-input-shadow</code> · <code>--xh-prompt-input-stop-bg</code> · <code>--xh-prompt-input-stop-bg-active</code> · <code>--xh-prompt-input-stop-bg-hover</code> · <code>--xh-prompt-input-stop-fg</code> · <code>--xh-prompt-input-stop-mark-radius</code> · <code>--xh-prompt-input-stop-mark-size</code> · <code>--xh-prompt-input-submit-font-size</code> · <code>--xh-prompt-input-submit-font-weight</code> · <code>--xh-prompt-input-submit-px</code> · <code>--xh-prompt-input-submit-radius</code> · <code>--xh-prompt-input-submit-shadow</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>border-color</code> · <code>border-radius</code> · <code>box-shadow</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>附件用<a href="./file-upload">文件上传</a>：它已覆盖 accept、大小校验、拖拽投放与逐条删除； 有附件而正文为空时把 <code>allowEmptySubmit</code> 置真。附件条摆在输入行上方，动作行摆在下方， 两者都是 root 的直接子节点，与输入行并列。</li><li>粘贴上传由作者在输入框上自己挂 <code>onPaste</code>，处理器会与组件的链式组合。</li><li>模型选择器用<a href="./select">选择器</a>或<a href="./combobox">组合框</a>，工具开关用<a href="./toggle-group">开关组</a>， 它们连同自己的容器一起摆进输入行下方的那一段。</li><li>与<a href="./message-feed">消息流</a>合起来就是一个最小对话界面。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>受控用法下提交后由宿主清空；<code>clearOnSubmit</code> 关掉时组件不动值。</li><li>生成期间把 <code>loading</code> 置真而不是把整个输入框禁用：用户还要能改下一句。</li><li>要药丸形状不必换形态轴：在任意祖先上写一行 <code>--xh-prompt-input-radius: var(--xh-shape-pill)</code>， 按钮那一颗另有 <code>--xh-prompt-input-submit-radius</code>。形态轴只管底与描边怎么画。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>另起一颗停止按钮摆在旁边：两颗按钮的位置会互相挤，且按下去的那一刻它正好换了位置。</li><li>用 <code>disabled</code> 表达「正在生成」：那会连输入一起挡住，也把停止的出口一起关掉。</li></ul>',48))])}const E=n(s,[["render",u]]);export{q as __pageData,E as default};
